<script setup lang="ts">
import { ref,computed,onMounted,onBeforeUnmount } from 'vue'
import ThemedSelect from './ThemedSelect.vue'
import Icon from '../console/components/Icon.vue'
import type { EditAction } from '../core/editor/core'
const props=defineProps<{disabled?:boolean;undo?:boolean;redo?:boolean;compact?:boolean;popupAbove?:boolean}>()
const emit=defineEmits<{(e:'action',action:EditAction):void;(e:'undo'):void;(e:'redo'):void}>()
const tools=[{id:'bold',label:'加粗',icon:'bold',key:'Ctrl+B'},{id:'italic',label:'斜体',icon:'italic',key:'Ctrl+I'},{id:'strike',label:'删除线',icon:'strike'},{id:'underline',label:'下划线',icon:'underline'},{id:'highlight',label:'高亮',icon:'pencil'},{id:'quote',label:'引用',icon:'quote'},{id:'bullet',label:'无序列表',icon:'list'},{id:'ordered',label:'有序列表',icon:'listOrdered'},{id:'task',label:'任务列表',icon:'check'},{id:'code',label:'行内代码',icon:'code'},{id:'link',label:'插入链接',icon:'link',key:'Ctrl+K'},{id:'image',label:'插入图片链接',icon:'image'},{id:'codeblock',label:'代码块',icon:'codeblock'},{id:'table',label:'插入表格',icon:'table'},{id:'math',label:'行内公式',icon:'formula'},{id:'mathblock',label:'独立公式',icon:'formula'},{id:'rule',label:'插入分隔线',icon:'minus'},{id:'footnote',label:'脚注',icon:'page'}]
let saved:string[]|undefined;try{saved=JSON.parse(localStorage.getItem('yh.editor.toolbar')||'null')}catch{}
const enabled=ref(Array.isArray(saved)?saved:['bold','italic','strike','underline','quote','bullet','ordered','code','link','codeblock']),open=ref(false),custom=ref(false),root=ref<HTMLElement>(),width=ref(900)
const chosen=computed(()=>tools.filter(t=>enabled.value.includes(t.id))),limit=computed(()=>Math.max(2,Math.min(props.compact?8:12,Math.floor((width.value-160)/32)))),visible=computed(()=>chosen.value.slice(0,limit.value)),overflow=computed(()=>tools.filter(t=>!visible.value.includes(t)))
function pick(id:string){if(props.disabled)return;emit('action',id as EditAction);open.value=false}
function toggle(id:string){enabled.value=enabled.value.includes(id)?enabled.value.filter(x=>x!==id):[...enabled.value,id];try{localStorage.setItem('yh.editor.toolbar',JSON.stringify(enabled.value))}catch{}}
let observer:ResizeObserver
function outside(e:PointerEvent){if(!root.value?.contains(e.target as Node)){open.value=false;custom.value=false}}
onMounted(()=>{observer=new ResizeObserver(entries=>width.value=entries[0].contentRect.width);observer.observe(root.value!);document.addEventListener('pointerdown',outside)})
onBeforeUnmount(()=>{observer?.disconnect();document.removeEventListener('pointerdown',outside)})
</script>
<template><div ref="root" class="editor-tools" :class="{ 'popup-above': popupAbove }" role="toolbar" aria-label="Markdown 工具栏" @keydown.esc.stop="open=false;custom=false" @pointerdown="e=>{if((e.target as HTMLElement).closest('button'))e.preventDefault()}">
<button type="button" aria-label="撤销" title="撤销 Ctrl+Z" :disabled="disabled||!undo" @click="emit('undo')"><Icon name="undo" :size="16"/></button><button type="button" aria-label="重做" title="重做 Ctrl+Shift+Z" :disabled="disabled||!redo" @click="emit('redo')"><Icon name="redo" :size="16"/></button><span class="et-divider"></span>
<ThemedSelect label="插入标题" placeholder="标题" model-value="" :options="[1,2,3,4,5,6].map(n => ({value:'h'+n,label:'H'+n}))" :disabled="disabled" @update:model-value="pick(String($event))" />
<button v-for="tool in visible" :key="tool.id" type="button" :aria-label="tool.label" :title="tool.label+(tool.key?' '+tool.key:'')" :disabled="disabled" @click="pick(tool.id)"><Icon :name="tool.icon" :size="16"/></button>
<button type="button" class="et-more" aria-label="更多 Markdown 工具" :aria-expanded="open" :disabled="disabled" @click="open=!open;custom=false"><Icon name="more" :size="17"/></button>
<Transition name="tool-menu"><div v-if="open" class="et-menu" role="menu"><button v-for="tool in overflow" :key="tool.id" type="button" role="menuitem" @click="pick(tool.id)"><Icon :name="tool.icon" :size="16"/><span>{{tool.label}}</span><small>{{tool.key}}</small></button><button type="button" role="menuitem" @click="custom=!custom"><Icon name="settings" :size="16"/>自定义工具栏</button><div v-if="custom" class="et-custom"><label v-for="tool in tools" :key="tool.id"><input type="checkbox" :checked="enabled.includes(tool.id)" @change="toggle(tool.id)"/>{{tool.label}}</label></div></div></Transition>
</div></template>
<style scoped>
.editor-tools{position:relative;display:flex;align-items:center;gap:2px;min-width:0;flex:1;color:var(--fg);height:32px}.editor-tools button,.editor-tools select{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:0;background:transparent;color:inherit;border-radius:6px;height:29px;padding:5px 7px;flex-shrink:0;font:inherit;font-size:12px;cursor:pointer;transition:background .14s,color .14s,transform .12s}.editor-tools button:hover,.editor-tools select:hover{background:var(--acc-soft)}.editor-tools button:active{transform:translateY(1px)}.editor-tools button:disabled,.editor-tools select:disabled{opacity:.4;cursor:default}.editor-tools :focus-visible{outline:2px solid var(--link,var(--acc));outline-offset:1px}.et-divider{height:17px;border-left:1px solid var(--line);margin:0 4px}.editor-tools .et-more{margin-left:auto}.et-menu{position:absolute;top:calc(100% + 5px);right:0;z-index:40;min-width:210px;max-height:min(380px,55vh);overflow:auto;padding:5px;background:var(--card);border:1px solid var(--line);border-radius:9px;box-shadow:0 8px 24px #0002}.editor-tools.popup-above .et-menu{top:auto;bottom:calc(100% + 6px);inset-inline:0;min-width:0;max-height:min(300px,38dvh);overscroll-behavior:contain;scrollbar-gutter:stable;box-sizing:border-box}
.popup-above .tool-menu-enter-from,.popup-above .tool-menu-leave-to{transform:translateY(4px)}
.et-menu button{width:100%;justify-content:flex-start;height:32px}.et-menu small{margin-left:auto;color:var(--fg2);font-size:10px}.et-custom{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:10px 4px;font-size:11px}.et-custom label{display:flex;align-items:center;gap:4px}.et-custom input{accent-color:var(--acc)}.tool-menu-enter-active,.tool-menu-leave-active{transition:opacity .14s,transform .14s}.tool-menu-enter-from,.tool-menu-leave-to{opacity:0;transform:translateY(-4px)}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style>
